import{_ as a,o as t,c as s,a6 as i}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Persistance et récupération durable","description":"","frontmatter":{"title":"Persistance et récupération durable","docId":"developer.storage","translationKey":"developer.storage","locale":"fr","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"7ec9d94e484af17e8e82aaaa2122cc47ecd206cf9306047795d6aaa72eea2edb","translationRevision":"0e624b59c2d4726cdc2ac3d046c0517be88e5d52d0fae069a0df39c38924aa87","order":60},"headers":[],"relativePath":"fr/developer/storage.md","filePath":"fr/developer/storage.md","lastUpdated":1794611623000}'),r={name:"fr/developer/storage.md"};function n(o,e,l,d,c,u){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="persistence-and-durable-recovery" tabindex="-1">Persistance et récupération durable <a class="header-anchor" href="#persistence-and-durable-recovery" aria-label="Permalink to &quot;Persistance et récupération durable {#persistence-and-durable-recovery}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Modifier l’état persistant via son service propriétaire et préserver les résultats récupérables. Utilisez un profil jetable, fermez son hôte avant de copier des bases et lisez les <a href="./control-api.html">métadonnées de contrôle</a> avant de modifier des ressources versionnées. <code>TIKTOOLS_HOME</code> sélectionne la racine de l’application ; <code>AppPaths</code> détermine ses données et stockages privés.</p><h2 id="identify-the-store" tabindex="-1">Identifier le stockage <a class="header-anchor" href="#identify-the-store" aria-label="Permalink to &quot;Identifier le stockage {#identify-the-store}&quot;">​</a></h2><p><code>crates/tiktools-core/src/paths.rs</code> définit <code>data/tiktok-points.db</code>, <code>data/tiktok-automation.db</code> et <code>data/tiktok-analytics.db</code>. Les modules de service SQLite possèdent leurs schémas. Points/spectateurs et définitions d’automatisation ont des registres métier distincts ; l’analytique est une base séparée, omise par les anciens schémas à deux bases.</p><p>Au démarrage, les anciennes bases locales au dépôt peuvent être copiées vers les données applicatives de la plateforme uniquement si la destination est absente. Une destination existante n’est jamais écrasée. Les définitions JSON restent lisibles pendant les changements d’exécution native. N’implémentez pas une migration en supprimant le profil d’un utilisateur ou en réécrivant les tables depuis Vue.</p><h2 id="make-a-recoverable-change" tabindex="-1">Effectuer un changement récupérable <a class="header-anchor" href="#make-a-recoverable-change" aria-label="Permalink to &quot;Effectuer un changement récupérable {#make-a-recoverable-change}&quot;">​</a></h2><ol><li>Repérez la transaction du service et ses tests de schéma/migration.</li><li>Stockez le changement métier, la révision et la réservation de journal/outbox requise dans la même transaction lorsque le domaine le permet.</li><li>Préservez les marqueurs de suppression des révisions. Un identifiant d’enregistrement réutilisé ne doit pas accepter une révision d’édition antérieure à sa suppression.</li><li>Publiez les métadonnées d’invalidation validées via l’outbox existante ; une nouvelle tentative de livraison ne doit pas répéter l’action sous-jacente.</li><li>Rouvrez le même répertoire de test privé après interruption et résolvez la commande originale avant une autre mutation.</li></ol><p>Vérifications utiles en lecture seule sur un hôte de test déjà actif :</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span></code></pre></div><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Les journaux durables pris en charge des workflows, points et propriétaires conservent les résultats originaux après redémarrage. Un reçu décrit sa commande historique ; lisez séparément l’état actuel. Les stockages des espaces Cloud ajoutent des partitions origine/compte et des vérifications de génération ; ils ne remplacent pas l’autorité SQLite locale. Tous les effets externes ou domaines n’ont pas la même couverture de récupération durable.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Conservez ensemble les fichiers SQLite et tout WAL/SHM actif lors d’une sauvegarde hors ligne. Un délai d’interface dépassé ne prouve pas une annulation. Pour <code>revision_conflict</code>, préservez le brouillon et comparez une nouvelle lecture. Pour des effets externes incertains, examinez l’enregistrement d’effet conservé plutôt que de rejouer un flux. Consultez la <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/paths.rs" target="_blank" rel="noreferrer">référence des chemins</a> et la <a href="./cloud.html">récupération Cloud</a> pour leurs frontières distinctes.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>Vérifiez les chemins avec <code>tiktools api call system.info --json</code> avant essais ou sauvegardes. <code>TIKTOOLS_HOME</code> choisit la racine ; <code>TIKTOOLS_DATA_DIR</code>, <code>TIKTOOLS_PLUGINS_DIR</code>, <code>TIKTOOLS_PLUGIN_DATA_DIR</code>, <code>TIKTOOLS_PLUGIN_STORE_DIR</code>, <code>TIKTOOLS_LOG_DIR</code>, <code>TIKTOOLS_TEMP_DIR</code> remplacent les dossiers dérivés. Les chemins relatifs dépendent du dossier de lancement. Une racine isolée ne neutralise pas les variables héritées : vérifiez/retirez-les d’abord.</p><p>Analytics contient des agrégats avec un écrivain dédié : file actuelle 1 024, lots 128, délai de vidage 10 s. Le fichier voisin <code>*.pending.json</code> dérive du chemin de sa base. Le démarrage rejoue les lots identifiés puis retire le fichier avant que <code>ready</code> autorise du travail. Récupération illisible/supérieure à 16 MiB, base indisponible ou retrait impossible maintiennent l’admission désactivée. Conservez base et fichier, examinez <code>ready</code>, éléments en attente et erreurs, puis sauvegardez avant réparation. N’effacez pas ces preuves pour masquer le problème ; les journaux de points ont un autre contrat durable.</p><p><code>system.info</code> indique home/dataDir effectifs ; résolvez les autres dossiers depuis l’environnement réel de lancement de l’hôte, pas un autre terminal. Utilisez <code>system.health</code> pour ready/attentes analytiques et compteurs LIVE.</p>`,18)])])}const m=a(r,[["render",n]]);export{h as __pageData,m as default};
